mapper.select:
SELECT account_status
FROM members
WHERE member_id = #{memberId}

SELECT suspended_until
FROM members
WHERE member_id = #{memberId}

mapper.update:
UPDATE members
SET account_status = 'SUSPENDED',
    suspended_until = #{suspendedUntil, jdbcType=TIMESTAMP}
WHERE member_id = #{memberId}
  AND account_status != 'INACTIVE'
